using DashboardManagement.Authorization; using DashboardManagement.Interfaces; using DashboardManagement.Services; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.AspNetCore.Authorization; using Microsoft.IdentityModel.Tokens; using System.Text; var builder=WebApplication.CreateBuilder(args);builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();builder.Services.AddHttpClient();builder.Services.AddScoped<IDashboardService,DashboardService>();builder.Services.AddAuthentication(o=>{o.DefaultAuthenticateScheme=JwtBearerDefaults.AuthenticationScheme;o.DefaultChallengeScheme=JwtBearerDefaults.AuthenticationScheme;o.DefaultScheme=JwtBearerDefaults.AuthenticationScheme;}).AddJwtBearer(o=>{o.SaveToken=true;o.RequireHttpsMetadata=false;o.TokenValidationParameters=new TokenValidationParameters{ValidIssuer=builder.Configuration["AppSettings:ValidIssuer"],ValidAudience=builder.Configuration["AppSettings:ValidAudience"],IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(builder.Configuration["AppSettings:Secret"]!)),ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=true,ValidateIssuerSigningKey=true,ClockSkew=TimeSpan.Zero};});builder.Services.AddAuthorization();builder.Services.AddSingleton<IAuthorizationHandler,PermissionAuthorizationHandler>();builder.Services.AddSingleton<IAuthorizationPolicyProvider,PermissionAuthorizationPolicyProvider>();builder.Services.AddHttpContextAccessor();var app=builder.Build();if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.Run("http://localhost:5230");